use vstd::prelude::*;

verus! {

fn remove_kth_element(list: &Vec<i32>, k: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        1 <= k,
        k < list.len(),
    ensures
        new_list.len() == list.len() - 1,

        // Elements before the removed position are unchanged
        forall|i: int|
            0 <= i < (k as int - 1) ==> new_list[i] == list[i],

        // Elements after the removed position shift left by 1
        forall|i: int|
            (k as int - 1) <= i < new_list.len() ==> new_list[i] == list[i + 1],
{
    // Preconditions (as stated): list is non-empty and 1 <= k < list.len()
    // k is 1-based; convert to 0-based index.
    let idx = k - 1;

    let mut new_list = Vec::with_capacity(list.len().saturating_sub(1));

    // Copy prefix [0 .. idx)
    new_list.extend_from_slice(&list[..idx]);
    // Copy suffix (idx+1 .. end)
    new_list.extend_from_slice(&list[idx + 1..]);

    new_list
}

} // verus!
